import { seed } from './seed.js';
import { cleanText, cleanUrl, hashPassword, verifyPassword, safeEqual, slug as makeSlug } from './security.js';

const root = path.dirname(fileURLToPath(import.meta.url));
const port = Number(process.env.PORT || 3030);
const dataDir = path.resolve(process.env.DATA_DIR || path.join(root, '..', 'data'));
const uploadDir = path.resolve(process.env.UPLOAD_DIR || path.join(root, '..', 'uploads'));
const db = process.env.DATABASE_URL
  ? new PostgresStore(process.env.DATABASE_URL)
  : new JsonStore(path.join(dataDir, 'store.json'));
const sessions = new Map();
const MAX_BODY = 8 * 1024 * 1024;

const html = (body) => `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stores Admin</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#17233d;background:#f5f7fb;--navy:#071b3a;--red:#e74343;--line:#dfe5ee}*{box-sizing:border-box}body{margin:0}header{background:var(--navy);color:white;padding:20px 5vw;display:flex;justify-content:space-between;align-items:center}main{max-width:1280px;margin:auto;padding:32px 5vw}.layout{display:grid;grid-template-columns:210px 1fr;gap:28px}.side{background:white;border:1px solid var(--line);border-radius:18px;padding:14px;height:max-content}.side a{display:block;padding:11px 12px;color:#52617a;text-decoration:none;border-radius:10px}.side a:hover,.side a.active{background:#edf2ff;color:var(--navy);font-weight:800}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:white;border:1px solid var(--line);border-radius:18px;padding:20px}.card h2,.card h3{margin-top:0}.stat{font-size:34px;font-weight:900}.table-wrap{overflow:auto;background:white;border:1px solid var(--line);border-radius:18px}table{border-collapse:collapse;width:100%;min-width:700px}th,td{text-align:left;padding:13px 16px;border-bottom:1px solid var(--line);vertical-align:middle}th{color:#61708a;font-size:12px;text-transform:uppercase;letter-spacing:.08em}button,.button{border:0;border-radius:10px;padding:10px 14px;background:var(--navy);color:white;font-weight:800;cursor:pointer;text-decoration:none;display:inline-block}button.danger{background:#b72f38}button.ghost{background:#eef2f8;color:var(--navy)}input,textarea,select{width:100%;border:1px solid #cbd5e1;border-radius:10px;padding:11px;margin:6px 0 14px;font:inherit}textarea{min-height:95px;resize:vertical}.actions{display:flex;gap:8px;flex-wrap:wrap}.flash{padding:12px 14px;border-radius:10px;background:#e6f7ec;color:#126233;margin-bottom:18px}.error{background:#fff0f0;color:#9d2020}.login{max-width:430px;margin:10vh auto}.muted{color:#66758e}.thumb{width:58px;height:46px;border-radius:8px;object-fit:cover;background:#eef2f8}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.full{grid-column:1/-1}@media(max-width:800px){.layout{grid-template-columns:1fr}.grid,.form-grid{grid-template-columns:1fr}main{padding:24px 4vw}}
</style></head><body>${body}</body></html>`;

function send(res, status, body, type = 'application/json; charset=utf-8', headers = {}) { res.writeHead(status, { 'content-type': type, ...headers }); res.end(type.startsWith('application/json') ? JSON.stringify(body) : body); }
function redirect(res, location) { res.writeHead(302, { location }); res.end(); }
function cookie(req, name) { return (req.headers.cookie || '').split(';').map(v => v.trim().split('=')).find(([key]) => key === name)?.[1]; }
async function body(req) { let raw = ''; for await (const chunk of req) { raw += chunk; if (raw.length > MAX_BODY) throw new Error('El cuerpo supera el límite permitido.'); } return raw ? JSON.parse(raw) : {}; }
function userFor(req) { const token = cookie(req, 'stores_session'); return token ? sessions.get(token) : null; }
function canAccess(user, storeId) { return user?.role === 'master' || user?.storeIds?.includes(storeId); }
function findStore(value) { return db.data.stores.find(store => store.id === value || store.slug === value || store.origin === value); }
const DEFAULT_WHATSAPP_MESSAGE = 'Hola, Importaciones EBC. Quiero solicitar este pedido y confirmar disponibilidad, envío y forma de pago:';
const DEFAULT_WHATSAPP_GREETING = 'Hola, Importaciones EBC. Quiero conocer sus productos y recibir asesoría, por favor.';
function settingsWithDefaults(store, settings = db.data.settings.find(item => item.storeId === store.id)) { return { storeId: store.id, storeName: store.name, ...settings, whatsappMessage: String(settings?.whatsappMessage || '').trim() || DEFAULT_WHATSAPP_MESSAGE, whatsappGreeting: String(settings?.whatsappGreeting || '').trim() || DEFAULT_WHATSAPP_GREETING }; }
function generatedDetails(product, category) { const categoryName = category?.name || 'producto seleccionado'; const short = String(product.description || '').replace(/<[^>]*>/g, '').trim(); return `<p><strong>${text(product.name)}</strong> es una opción seleccionada de nuestra categoría de ${text(categoryName).toLowerCase()}.</p>${short ? `<p>${text(short)}</p>` : `<p>Una alternativa práctica para complementar tu rutina y recibirla directamente en Colombia.</p>`}<h3>Compra acompañada</h3><ul><li>Producto revisado antes de confirmar disponibilidad.</li><li>Precio de referencia sujeto a disponibilidad y envío.</li><li>Te asesoramos por WhatsApp para coordinar tu pedido.</li></ul>`; }
function detailsForProduct(product, categories) { return { ...product, detailsHtml: String(product.detailsHtml || '').trim() || generatedDetails(product, categories.find(category => category.id === product.categoryId)) }; }
function publicCatalog(store) { const categories = db.data.categories.filter(item => item.storeId === store.id && item.active).sort((a,b) => a.sortOrder-b.sortOrder); const products = db.data.products.filter(item => item.storeId === store.id && item.active && item.available).sort((a,b) => a.sortOrder-b.sortOrder).map(product => detailsForProduct(product, categories)); return { store, settings: settingsWithDefaults(store), categories, products, featuredProducts: products.filter(product => product.featured) }; }
function validateRecord(collectionName, input) {
  if (collectionName === 'categories' && !cleanText(input.name, 120)) throw new Error('El nombre de la categoría es obligatorio.');
  if (collectionName === 'products' && (!cleanText(input.name, 160) || !input.categoryId || Number(input.price) < 0)) throw new Error('Producto inválido: nombre, categoría y precio son obligatorios.');
  if (collectionName === 'settings' && input.whatsappNumber && !/^\d{8,15}$/.test(String(input.whatsappNumber).replace(/\D/g, ''))) throw new Error('El número de WhatsApp debe contener solo dígitos.');
}
function sessionCookie(token) { const secure = process.env.COOKIE_SECURE === 'true'; return `stores_session=${token}; HttpOnly; SameSite=${secure ? 'None' : 'Lax'}; Path=/; Max-Age=28800${secure ? '; Secure' : ''}`; }
function nav(active) { return `<aside class="side"><a class="${active==='dashboard'?'active':''}" href="/storeadmin/">Resumen</a><a class="${active==='stores'?'active':''}" href="/storeadmin/stores">Tiendas</a><a class="${active==='catalog'?'active':''}" href="/storeadmin/catalog">Categorías</a><a href="/storeadmin/products">Productos</a><a href="/storeadmin/logout">Cerrar sesión</a></aside>`; }
const proAdminCss = `<style>:root{--admin-navy:#2e4356;--admin-navy-dark:#26394b;--admin-blue:#36a3f7;--admin-bg:#eef1f5;--admin-line:#e4e8ed;--admin-text:#46515c}*{box-sizing:border-box}body{margin:0;background:var(--admin-bg);color:var(--admin-text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.pro-header{height:58px;position:sticky;top:0;z-index:10;background:#fff;border-bottom:1px solid var(--admin-line);padding:0 26px;display:flex;align-items:center;justify-content:space-between;box-shadow:0 1px 5px #26394b12}.pro-brand{height:58px;display:flex;align-items:center;gap:10px;color:#26394b;font-weight:800;font-size:17px}.pro-brand-mark{display:grid;place-items:center;width:30px;height:30px;border-radius:7px;background:#4389e8;color:#fff;font-size:11px}.pro-header-right{display:flex;align-items:center;gap:16px;color:#69747e;font-size:12px}.pro-user{padding:7px 12px;border-radius:18px;background:#f4f6f8;color:#53606c}.pro-logout{color:#df4c57;text-decoration:none;font-weight:800}.pro-main{max-width:none;padding:0}.pro-layout{display:grid;grid-template-columns:238px minmax(0,1fr);gap:0;min-height:calc(100vh - 58px)}.pro-side{background:var(--admin-navy);border:0;border-radius:0;padding:20px 0;height:auto;min-height:calc(100vh - 58px);box-shadow:none}.pro-side-title{padding:0 24px 25px;color:#dce5ed;font-size:16px;font-weight:800;letter-spacing:0;text-transform:none}.pro-side a{display:flex;align-items:center;color:#c8d3dd;border-left:3px solid transparent;border-radius:0;padding:12px 24px;margin:0;font-size:13px;transition:.15s}.pro-side a::before{content:"";width:5px;height:5px;border-radius:50%;margin-right:11px;background:#8fa2b1}.pro-side a:hover,.pro-side a.active{background:var(--admin-navy-dark);border-left-color:var(--admin-blue);color:#fff;box-shadow:none}.pro-side a.active::before{background:var(--admin-blue)}.pro-content{padding:25px 22px 50px;min-width:0}.pro-content>h1{margin:0 0 18px;font-size:24px;letter-spacing:-.025em;color:#3e4a55;font-weight:700}.pro-content .grid{gap:14px}.pro-content .card{border:1px solid var(--admin-line);border-radius:3px;box-shadow:0 1px 4px #26394b0b;background:#fff}.pro-content .stat{font-size:30px;color:#26394b}.pro-content .table-wrap{border:1px solid var(--admin-line);border-radius:3px;box-shadow:none;background:#fff;overflow:auto}.pro-content table{width:100%;border-collapse:collapse;font-size:12px}.pro-content th{background:#fafbfc;color:#68737d;font-size:11px;font-weight:700;text-transform:none;white-space:nowrap;border-bottom:1px solid var(--admin-line);padding:10px 11px}.pro-content td{border-bottom:1px solid #edf0f3;padding:9px 11px;vertical-align:middle}.pro-content tr:last-child td{border-bottom:0}.pro-content tr:hover td{background:#fbfdff}.pro-content .button{background:#35a4f5;border-radius:3px;padding:8px 12px;font-size:12px}.pro-content .button.ghost{background:#eef2f5;color:#52606c;border-radius:3px}.pro-content button{border-radius:3px;padding:8px 12px;font-size:12px}.pro-content input,.pro-content select{border:1px solid #d7dde4;border-radius:3px;padding:7px 8px;background:#fff;color:#3e4a55;font-size:12px}.pro-content label{font-size:12px}.pro-content .flash{display:inline-block;margin:0;padding:5px 8px;border-radius:3px;font-size:11px}.pro-content .form-grid{gap:12px}.pro-content code{display:inline-block;max-width:220px;overflow:hidden;text-overflow:ellipsis;vertical-align:middle;color:#52677d;background:#f2f4f6;padding:4px 6px;border-radius:3px;font-size:10px}.side-store-picker{margin:0 16px 25px;padding:12px;background:#26394b;border:1px solid #46647b;border-radius:3px}.side-store-picker label{display:block;color:#dce5ed;font-size:11px;font-weight:800;margin-bottom:7px}.side-store-picker select{width:100%;padding:8px 7px;border:1px solid #61798c;border-radius:3px;background:#fff;color:#344553;font-size:11px}.side-help{margin:28px 16px 0;padding:13px;border-radius:3px;background:#31556d;color:#d7e3ec;font-size:11px;line-height:1.45}.side-help strong{display:block;color:#fff;margin-bottom:5px}.catalog-create-card{border-radius:3px!important;box-shadow:0 1px 4px #26394b0b!important}.catalog-create-card h2{font-size:17px!important;color:#3e4a55}.catalog-create-card .form-grid{gap:10px!important}.catalog-create-card input,.catalog-create-card select{border-radius:3px!important}.catalog-create-card button{border-radius:3px!important}.upload-drop{border-radius:3px!important;min-height:82px!important;padding:9px!important}.upload-preview{width:62px!important;height:62px!important;border-radius:3px!important}.admin-image-cell{display:inline-flex;align-items:center;justify-content:center;position:relative}.admin-image-cell img,.admin-image-cell .thumb{cursor:help}.admin-image-cell[title]:hover:after{content:attr(title);position:absolute;z-index:20;left:0;top:calc(100% + 6px);min-width:220px;max-width:360px;padding:7px 9px;border-radius:3px;background:#26394b;color:#fff;font-size:11px;font-weight:500;line-height:1.3;white-space:normal;box-shadow:0 4px 12px #26394b33;pointer-events:none}@media(max-width:800px){.pro-layout{grid-template-columns:1fr}.pro-side{min-height:auto;padding:10px 0}.pro-side-title{padding:8px 18px 12px}.pro-side a{display:inline-flex;padding:9px 14px}.side-help{display:none}.pro-content{padding:20px 14px 35px}.pro-header{padding:0 14px}.pro-header-right .pro-user{display:none}.pro-content>h1{font-size:22px}}</style>`;
function shell(user, active, title, content, sidebarExtra = '') { return html(`${proAdminCss}<header class="pro-header"><div class="pro-brand"><span class="pro-brand-mark">SA</span><span>Stores Admin</span></div><div class="pro-header-right"><span class="pro-user">${text(user.email)} · ${text(user.role)}</span><a class="pro-logout" href="/storeadmin/logout">Salir</a></div></header><main class="pro-main"><div class="layout pro-layout"><aside class="side pro-side"><div class="pro-side-title">Administración</div>${sidebarExtra}${nav(active).replace('<aside class="side">','').replace('</aside>','')}<div class="side-help"><strong>Panel multi-tienda</strong>Gestiona catálogo, accesos y configuraciones desde un solo lugar.</div></aside><section class="pro-content"><h1>${title}</h1>${content}</section></div></main>`); }
function catalogSidebar(stores, selectedId, section = "categories") { const selected = stores.find(store => store.id === selectedId) || stores[0]; if (!selected) return ""; return `<div class="side-store-picker"><form method="get" action="/storeadmin/${section}"><label>Tienda seleccionada<select name="storeId" onchange="this.form.submit()">${stores.map(store => `<option value="${text(store.id)}" ${store.id === selected.id ? "selected" : ""}>${text(store.name)}</option>`).join("")}</select></label></form></div>`; }
function loginPage(error = '') { return html(`<main class="login card"><h1>Acceso administrativo</h1><p class="muted">Configura tus tiendas desde un único panel.</p>${error ? `<div class="flash error">${error}</div>` : ''}<form method="post" action="/storeadmin/login"><label>Correo<input name="email" type="email" required autocomplete="username"></label><label>Contraseña<input name="password" type="password" required autocomplete="current-password"></label><button>Ingresar</button></form></main>`); }
async function formBody(req) { const raw = await new Promise((resolve, reject) => { let value=''; req.on('data', c => value += c); req.on('end', () => resolve(value)); req.on('error', reject); }); return Object.fromEntries(new URLSearchParams(raw)); }
function text(value) { return String(value ?? '').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;'); }

function storeAdminForm(store = {}, error = '') {
  return `<div class="card"><h2>${store.id ? 'Editar tienda' : 'Nueva tienda'}</h2>${error ? `<div class="flash error">${text(error)}</div>` : ''}<form method="post" action="${store.id ? `/storeadmin/stores/${store.id}` : '/storeadmin/stores'}"><div class="form-grid"><label>Nombre<input name="name" value="${text(store.name)}" required></label><label>Slug<input name="slug" value="${text(store.slug)}" placeholder="mi-tienda" required></label><label class="full">Origen público<input name="origin" type="url" value="${text(store.origin)}" placeholder="https://mitienda.com" required></label>${store.id ? `<label class="check"><input name="active" type="checkbox" ${store.active ? 'checked' : ''}> Tienda activa</label><label class="check"><input name="rotateApiKey" type="checkbox"> Regenerar clave API</label>` : `<label>Correo del administrador<input name="adminEmail" type="email" required></label><label>Contraseña inicial<input name="adminPassword" type="password" minlength="8" required></label>`}</div><div class="actions"><button class="button" type="submit">${store.id ? 'Guardar tienda' : 'Crear tienda'}</button><a class="button ghost" href="/storeadmin/stores">Cancelar</a></div></form></div>`;
}

function storeList(user, stores) {
  return `<div class="card"><div class="actions" style="justify-content:space-between"><div><h2>Tiendas registradas</h2><p class="muted">Cada tienda tiene su propio origen, clave API y administrador.</p></div><a class="button" href="/storeadmin/stores/new">+ Nueva tienda</a></div><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Origen</th><th>Administrador</th><th>Clave API</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${stores.map(store => { const admins = db.data.users.filter(candidate => candidate.role === 'store_admin' && candidate.storeIds?.includes(store.id)).map(candidate => candidate.email).join(', '); return `<tr><td><strong>${text(store.name)}</strong><br><small>${text(store.slug)}</small></td><td><a href="${text(store.origin)}" target="_blank" rel="noreferrer">${text(store.origin)}</a></td><td>${text(admins || 'Sin asignar')}</td><td><code>${user.role === 'master' ? text(store.apiKey) : 'Oculta'}</code></td><td>${store.active ? '<span class="flash">Activa</span>' : '<span class="muted">Inactiva</span>'}</td><td><div class="actions"><a class="button ghost" href="/storeadmin/stores/${store.id}/edit">Editar</a><a class="button ghost" href="${text(store.origin)}/admin" target="_blank" rel="noreferrer">Abrir panel</a></div></td></tr>`; }).join('')}</tbody></table></div></div>`;
}

function centralCatalogPage(user, stores, selectedId, notice = '', section = 'all', categoryId = '') {
  const selected = stores.find(store => store.id === selectedId) || stores[0];
  if (!selected) return '<div class="card"><h2>No hay tiendas disponibles</h2><p class="muted">Crea una tienda para comenzar a administrar su catálogo.</p></div>';
  const categories = db.data.categories.filter(item => item.storeId === selected.id).sort((a, b) => a.sortOrder - b.sortOrder);
  const products = db.data.products.filter(item => item.storeId === selected.id).sort((a, b) => a.sortOrder - b.sortOrder);
  const productRows = section === 'products' && categoryId ? products.filter(product => product.categoryId === categoryId) : products;
  const showCategories = section !== 'products'; const showProducts = section !== 'categories';
  const formStyles = `<style>.catalog-create-card{padding:18px;background:linear-gradient(180deg,#fff,#f9fbff);border:1px solid #e1e9f5;border-radius:16px;box-shadow:0 8px 20px #17233d0b}.catalog-create-card h2{margin:0 0 4px;font-size:20px}.catalog-create-card>form{margin-top:16px}.catalog-create-card .form-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;align-items:end}.catalog-create-card label{display:block;color:#40516d;font-size:11px;font-weight:800}.catalog-create-card input,.catalog-create-card select{margin-top:4px;padding:8px 10px;background:#fff;border-color:#cbd8ea;font-size:13px}.catalog-create-card button{margin-top:14px;padding:10px 16px;background:linear-gradient(135deg,#173f91,#2f67d7);box-shadow:0 6px 12px #2f67d733}.image-upload-field{grid-column:1/-1}.image-upload-field>span:first-child{display:block;margin-bottom:5px}.upload-drop{position:relative;display:flex;align-items:center;gap:12px;min-height:100px;padding:12px;border:2px dashed #b9cbea;border-radius:12px;background:#f6f9ff;cursor:pointer;transition:.2s}.upload-drop:hover{border-color:#2f67d7;background:#eef5ff}.upload-drop input{position:absolute;inset:0;width:100%;height:100%;opacity:0;cursor:pointer;margin:0}.upload-copy{display:flex;flex-direction:column;gap:3px;color:#52617a}.upload-copy strong{color:#173f91;font-size:13px}.upload-copy small{font-weight:500;color:#73829a;font-size:11px}.upload-preview{display:none;width:80px;height:80px;object-fit:cover;border-radius:10px;border:1px solid #d7e1f0;box-shadow:0 4px 10px #17233d18}.upload-preview[src]{display:block}@media(max-width:900px){.catalog-create-card .form-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.catalog-create-card .form-grid{grid-template-columns:1fr}.upload-drop{min-height:100px}.upload-preview{width:72px;height:72px}}</style>`;
  const storeSelector = `<div class="card"><form method="get" action="/storeadmin/catalog"><label><strong>Tienda seleccionada</strong><select name="storeId" onchange="this.form.submit()">${stores.map(store => `<option value="${text(store.id)}" ${store.id === selected.id ? 'selected' : ''}>${text(store.name)} — ${text(store.origin)}</option>`).join('')}</select></label></form><p class="muted">Edita aquí las categorías y productos que consume el storefront público.</p></div>`;
  const categoryForm = `<div class="card catalog-create-card"><h2>Categorías (${categories.length})</h2><form id="new-category-form" method="post" action="/storeadmin/catalog/category"><input type="hidden" name="storeId" value="${text(selected.id)}"><div class="form-grid"><label>Nombre<input name="name" required></label><label>Descripción<input name="description"></label><input id="new-category-image-url" type="hidden" name="imageUrl"><label class="image-upload-field"><span>Imagen de categoría</span><span class="upload-drop"><input id="new-category-image" type="file" accept="image/jpeg,image/png,image/webp"><span class="upload-copy"><strong>Haz clic para seleccionar una imagen</strong><small>JPG, PNG o WEBP · máximo 5 MB · se optimiza automáticamente</small></span><img id="new-category-preview" class="upload-preview" alt="Vista previa"></span></label><label>Orden<input name="sortOrder" type="number" value="${categories.length + 1}"></label></div><button type="submit">+ Crear categoría</button></form><script>document.addEventListener("DOMContentLoaded",()=>{const form=document.getElementById("new-category-form"),file=document.getElementById("new-category-image"),url=document.getElementById("new-category-image-url"),preview=document.getElementById("new-category-preview");if(!form)return;file.addEventListener("change",()=>{const selected=file.files?.[0];if(!selected)return;preview.src=URL.createObjectURL(selected);preview.style.display="block";});form.addEventListener("submit",async event=>{const selected=file.files?.[0];if(!selected||url.value)return;event.preventDefault();const submit=form.querySelector("button[type=submit]");submit.disabled=true;submit.textContent="Optimizando imagen…";const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(selected);});const response=await fetch("/storeadmin/api/uploads",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json"},body:JSON.stringify({dataUrl})});const result=await response.json();if(!response.ok){submit.disabled=false;submit.textContent="Crear categoría";alert(result.error||"No se pudo cargar la imagen.");return;}url.value=new URL(result.url,window.location.origin).toString();form.submit();});});</script><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Descripción</th><th>Productos vinculados</th><th>Imagen</th><th>Estado</th><th></th></tr></thead><tbody>${categories.map(category => `<tr><form method="post" action="/storeadmin/catalog/category"><input type="hidden" name="storeId" value="${text(selected.id)}"><input type="hidden" name="id" value="${text(category.id)}"><td><input name="name" value="${text(category.name)}" required></td><td><input name="description" value="${text(category.description)}"></td><td><strong>${products.filter(product => product.categoryId === category.id).length}</strong><br><small>${products.filter(product => product.categoryId === category.id).map(product => text(product.name)).join(' · ') || 'Sin productos'}</small></td><td><span class="admin-image-cell" title="${text(category.imageUrl || "Sin imagen")}">${category.imageUrl ? `<img class="thumb" src="${text(category.imageUrl)}" alt="${text(category.name)}">` : `<span class="thumb">Sin imagen</span>`}</span><input name="imageUrl" type="hidden" value="${text(category.imageUrl)}"></td><td><label><input name="active" type="checkbox" ${category.active ? 'checked' : ''}> Activa</label></td><td><button type="submit">Guardar</button> <a class="button ghost" href="/storeadmin/products?storeId=${encodeURIComponent(selected.id)}&categoryId=${encodeURIComponent(category.id)}">Ver productos</a></td></form></tr>`).join('')}</tbody></table></div></div>`;
  const productForm = `<div class="catalog-create-card"><h2>Productos (${productRows.length})</h2><form id="new-product-form" method="post" action="/storeadmin/catalog/product"><input type="hidden" name="storeId" value="${text(selected.id)}"><input id="new-product-image-url" type="hidden" name="imageUrl"><div class="form-grid"><label>Nombre<input name="name" required></label><label>Categoría<select name="categoryId" required>${categories.map(category => `<option value="${text(category.id)}">${text(category.name)}</option>`).join('')}</select></label><label>Precio COP<input name="price" type="number" min="0" value="0" required></label><label class="image-upload-field"><span>Imagen del producto</span><span class="upload-drop"><input id="new-product-image" type="file" accept="image/jpeg,image/png,image/webp"><span class="upload-copy"><strong>Haz clic para seleccionar una imagen</strong><small>JPG, PNG o WEBP · máximo 5 MB · se optimiza automáticamente</small></span><img id="new-product-preview" class="upload-preview" alt="Vista previa"></span></label><label>Fallback<input name="fallback" value="🛍️"></label><label>Orden<input name="sortOrder" type="number" value="${productRows.length + 1}"></label><label class="check"><input name="featured" type="checkbox"> Destacado</label></div><button type="submit">+ Crear producto</button></form><script>document.addEventListener("DOMContentLoaded",()=>{const form=document.getElementById("new-product-form"),file=document.getElementById("new-product-image"),url=document.getElementById("new-product-image-url"),preview=document.getElementById("new-product-preview");if(!form)return;file.addEventListener("change",()=>{const selected=file.files?.[0];if(!selected)return;preview.src=URL.createObjectURL(selected);preview.style.display="block";});form.addEventListener("submit",async event=>{const selected=file.files?.[0];if(!selected||url.value)return;event.preventDefault();const submit=form.querySelector("button[type=submit]");submit.disabled=true;submit.textContent="Optimizando imagen…";const dataUrl=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(selected);});const response=await fetch("/storeadmin/api/uploads",{method:"POST",credentials:"same-origin",headers:{"content-type":"application/json"},body:JSON.stringify({dataUrl})});const result=await response.json();if(!response.ok){submit.disabled=false;submit.textContent="Crear producto";alert(result.error||"No se pudo cargar la imagen.");return;}url.value=new URL(result.url,window.location.origin).toString();form.submit();});});</script><div class="table-wrap"><table><thead><tr><th>Producto</th><th>Categoría</th><th>Precio</th><th>Imagen</th><th>Estado</th><th></th></tr></thead><tbody>${productRows.map(product => `<tr><form method="post" action="/storeadmin/catalog/product"><input type="hidden" name="storeId" value="${text(selected.id)}"><input type="hidden" name="id" value="${text(product.id)}"><td><input name="name" value="${text(product.name)}" required></td><td><select name="categoryId">${categories.map(category => `<option value="${text(category.id)}" ${category.id === product.categoryId ? 'selected' : ''}>${text(category.name)}</option>`).join('')}</select></td><td><input name="price" type="number" min="0" value="${Number(product.price)}" required></td><td><span class="admin-image-cell" title="${text(product.imageUrl || "Sin imagen")}">${product.imageUrl ? `<img class="thumb" src="${text(product.imageUrl)}" alt="${text(product.name)}">` : `<span class="thumb">${text(product.fallback || '🛍️')}</span>`}</span><input name="imageUrl" type="hidden" value="${text(product.imageUrl)}"><input name="fallback" value="${text(product.fallback || '🛍️')}"></td><td><label><input name="active" type="checkbox" ${product.active ? 'checked' : ''}> Activo</label><label><input name="featured" type="checkbox" ${product.featured ? 'checked' : ''}> Destacado</label></td><td><button type="submit">Guardar</button></td></form></tr>`).join('')}</tbody></table></div></div>`;
  return `${formStyles}${notice ? `<div class="flash">${text(notice)}</div>` : ''}${showCategories ? categoryForm : ''}${showProducts ? productForm : ''}`;
}

function centralCatalogGridPage(user, stores, selectedId, notice = '') {
  const selected = stores.find(store => store.id === selectedId) || stores[0];
  if (!selected) return '<div class="card"><h2>No hay tiendas disponibles</h2><p class="muted">Crea una tienda para comenzar a administrar su catálogo.</p></div>';
  const categories = db.data.categories.filter(item => item.storeId === selected.id).sort((a, b) => a.sortOrder - b.sortOrder);
  const products = db.data.products.filter(item => item.storeId === selected.id).sort((a, b) => a.sortOrder - b.sortOrder);
  const image = (url, fallback, alt) => url ? `<img src="${text(url)}" alt="${text(alt)}">` : `<span class="catalog-fallback">${text(fallback || '🛍️')}</span>`;
  const styles = `<style>.catalog-toolbar{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:22px}.catalog-toolbar h2{margin:0}.catalog-toolbar form{min-width:360px}.catalog-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:18px;margin:18px 0 34px}.catalog-card{background:#fff;border:1px solid #dfe5ee;border-radius:20px;overflow:hidden;box-shadow:0 8px 24px #17233d0d}.catalog-card-media{height:170px;display:grid;place-items:center;background:linear-gradient(135deg,#edf4ff,#f9e8df);overflow:hidden}.catalog-card-media img{width:100%;height:100%;object-fit:cover}.catalog-fallback{font-size:68px}.catalog-card-body{padding:18px}.catalog-card-body h3{margin:0 0 5px;font-size:19px}.catalog-meta{color:#66758e;font-size:13px;margin-bottom:14px}.catalog-related{display:flex;flex-wrap:wrap;gap:6px;margin:10px 0 14px}.catalog-related strong{width:100%;font-size:11px;color:#52617a;text-transform:uppercase;letter-spacing:.08em}.catalog-related span{padding:5px 8px;border-radius:999px;background:#eef2f8;color:#17233d;font-size:11px}.catalog-card label{display:block;color:#52617a;font-size:12px;font-weight:800;margin-top:10px}.catalog-card input,.catalog-card select{margin:5px 0 0;padding:9px;font-size:13px}.catalog-card-actions{display:flex;gap:8px;align-items:center;margin-top:16px}.catalog-card-actions button{flex:1}.catalog-section-title{display:flex;justify-content:space-between;align-items:end;margin-top:26px}.catalog-section-title h2{margin-bottom:4px}.catalog-section-title p{margin:0;color:#66758e}.catalog-empty{padding:25px;border:1px dashed #cbd5e1;border-radius:16px;color:#66758e;background:#fff}@media(max-width:800px){.catalog-toolbar{display:block}.catalog-toolbar form{min-width:0;margin-top:15px}.catalog-grid{grid-template-columns:1fr}}</style>`;
  const selector = `<div class="catalog-toolbar"><div><p class="muted">Catálogo central</p><h2>${text(selected.name)}</h2><p class="muted">${text(selected.origin)}</p></div><form method="get" action="/storeadmin/catalog"><label>Tienda seleccionada<select name="storeId" onchange="this.form.submit()">${stores.map(store => `<option value="${text(store.id)}" ${store.id === selected.id ? 'selected' : ''}>${text(store.name)}</option>`).join('')}</select></label></form></div>`;
  const categoryCards = categories.map(category => `<article class="catalog-card"><div class="catalog-card-media">${image(category.imageUrl, '▦', category.name)}</div><div class="catalog-card-body"><h3>${text(category.name)}</h3><div class="catalog-meta">Categoría · ${category.active ? 'Activa' : 'Inactiva'}</div><div class="catalog-related"><strong>Productos vinculados</strong>${products.filter(product => product.categoryId === category.id).map(product => `<span>${text(product.name)}</span>`).join('') || '<span>Sin productos</span>'}</div><form method="post" action="/storeadmin/catalog/category"><input type="hidden" name="storeId" value="${text(selected.id)}"><input type="hidden" name="id" value="${text(category.id)}"><label>Nombre<input name="name" value="${text(category.name)}" required></label><label>Descripción<input name="description" value="${text(category.description)}"></label><label>Imagen URL<input name="imageUrl" type="url" value="${text(category.imageUrl)}"></label><label><input name="active" type="checkbox" ${category.active ? 'checked' : ''}> Categoría activa</label><div class="catalog-card-actions"><button type="submit">Guardar cambios</button><a class="button ghost" href="${text(selected.origin)}/admin" target="_blank" rel="noreferrer">Panel tienda</a></div></form></div></article>`).join('');
  const productCards = products.map(product => `<article class="catalog-card"><div class="catalog-card-media">${image(product.imageUrl, product.fallback, product.name)}</div><div class="catalog-card-body"><h3>${text(product.name)}</h3><div class="catalog-meta">${text(categories.find(category => category.id === product.categoryId)?.name || 'Sin categoría')} · $${Number(product.price).toLocaleString('es-CO')}</div><form method="post" action="/storeadmin/catalog/product"><input type="hidden" name="storeId" value="${text(selected.id)}"><input type="hidden" name="id" value="${text(product.id)}"><label>Nombre<input name="name" value="${text(product.name)}" required></label><label>Categoría<select name="categoryId">${categories.map(category => `<option value="${text(category.id)}" ${category.id === product.categoryId ? 'selected' : ''}>${text(category.name)}</option>`).join('')}</select></label><label>Precio COP<input name="price" type="number" min="0" value="${Number(product.price)}" required></label><label>Imagen URL<input name="imageUrl" type="url" value="${text(product.imageUrl)}"></label><label>Fallback<input name="fallback" value="${text(product.fallback || '🛍️')}"></label><label><input name="active" type="checkbox" ${product.active ? 'checked' : ''}> Producto activo</label><label><input name="featured" type="checkbox" ${product.featured ? 'checked' : ''}> Producto destacado</label><div class="catalog-card-actions"><button type="submit">Guardar cambios</button></div></form></div></article>`).join('');
  const newCategory = `<article class="catalog-card"><div class="catalog-card-media"><span class="catalog-fallback">＋</span></div><div class="catalog-card-body"><h3>Nueva categoría</h3><div class="catalog-meta">Añade una sección al catálogo</div><form method="post" action="/storeadmin/catalog/category"><input type="hidden" name="storeId" value="${text(selected.id)}"><label>Nombre<input name="name" required></label><label>Descripción<input name="description"></label><label>Imagen URL<input name="imageUrl" type="url" placeholder="https://..."></label><div class="catalog-card-actions"><button type="submit">Crear categoría</button></div></form></div></article>`;
  const newProduct = `<article class="catalog-card"><div class="catalog-card-media"><span class="catalog-fallback">＋</span></div><div class="catalog-card-body"><h3>Nuevo producto</h3><div class="catalog-meta">Añade un producto al catálogo</div><form method="post" action="/storeadmin/catalog/product"><input type="hidden" name="storeId" value="${text(selected.id)}"><label>Nombre<input name="name" required></label><label>Categoría<select name="categoryId" required>${categories.map(category => `<option value="${text(category.id)}">${text(category.name)}</option>`).join('')}</select></label><label>Precio COP<input name="price" type="number" min="0" value="0" required></label><label>Imagen URL<input name="imageUrl" type="url" placeholder="https://..."></label><label>Fallback<input name="fallback" value="🛍️"></label><div class="catalog-card-actions"><button type="submit">Crear producto</button></div></form></div></article>`;
  return `${styles}${notice ? `<div class="flash">${text(notice)}</div>` : ''}${selector}<div class="catalog-section-title"><div><h2>Categorías</h2><p>Imágenes y clasificación de la tienda</p></div></div><div class="catalog-grid">${newCategory}${categoryCards || '<div class="catalog-empty">No hay categorías todavía.</div>'}</div><div class="catalog-section-title"><div><h2>Productos</h2><p>Precios, imágenes y disponibilidad</p></div></div><div class="catalog-grid">${newProduct}${productCards || '<div class="catalog-empty">No hay productos todavía.</div>'}</div>`;
}

async function handleApi(req, res, pathname) {
  // Mantener la API sincronizada con cambios hechos directamente en PostgreSQL.
  await db.reload();
  const origin = req.headers.origin;
  if (origin && !db.data.stores.some(store => store.origin === origin) && !origin.includes('cesarvargas.tech')) return send(res, 403, { error: 'Origen no autorizado.' });
  if (req.method === 'OPTIONS') return send(res, 204, '', 'text/plain', { 'access-control-allow-origin': origin || '*', 'access-control-allow-credentials': 'true', 'access-control-allow-headers': 'content-type,x-store-api-key', 'access-control-allow-methods': 'GET,POST,PATCH,DELETE,OPTIONS' });
  const parts = pathname.split('/').filter(Boolean);
  if (pathname === '/storeadmin/api/session' && req.method === 'POST') {
    const input = await body(req); const user = db.data.users.find(u => u.email === String(input.email || '').toLowerCase());
    if (!user || !verifyPassword(input.password || '', user.passwordHash)) return send(res, 401, { error: 'Correo o contraseña incorrectos.' });
    const token = crypto.randomBytes(32).toString('hex'); sessions.set(token, user); return send(res, 200, { user: { id: user.id, email: user.email, role: user.role } }, 'application/json; charset=utf-8', { 'set-cookie': sessionCookie(token) });
  }
  if (pathname === '/storeadmin/api/session' && req.method === 'GET') { const user = userFor(req); if (!user) return send(res, 401, { error: 'Autenticación requerida.' }); return send(res, 200, { user: { id: user.id, email: user.email, role: user.role } }); }
  if (pathname === '/storeadmin/api/session' && req.method === 'DELETE') { sessions.delete(cookie(req, 'stores_session')); return send(res, 200, { ok: true }, 'application/json; charset=utf-8', { 'set-cookie': 'stores_session=; Max-Age=0; Path=/' }); }
  if (req.method === 'POST' && parts[2] === 'uploads') {
    const user = userFor(req); if (!user) return send(res, 401, { error: 'Autenticación requerida.' });
    const input = await body(req); const match = String(input.dataUrl || '').match(/^data:(image\/(?:png|jpeg|webp));base64,(.+)$/);
    if (!match) return send(res, 400, { error: 'Solo se permiten imágenes JPG, PNG o WEBP.' });
    const buffer = Buffer.from(match[2], 'base64'); if (buffer.length > 5 * 1024 * 1024) return send(res, 413, { error: 'La imagen supera el máximo de 5 MB.' });
    const optimized = await sharp(buffer).rotate().resize({ width: 1600, height: 1600, fit: 'inside', withoutEnlargement: true }).webp({ quality: 82, effort: 4 }).toBuffer();
    const filename = `${crypto.randomUUID()}.webp`; await fs.writeFile(path.join(uploadDir, filename), optimized); return send(res, 201, { url: `/storeadmin/uploads/${filename}`, filename, bytes: optimized.length, contentType: 'image/webp' });
  }
  if (req.method === 'GET' && parts[2] === 'catalog') {
    const store = findStore(parts[3]); if (!store || !store.active) return send(res, 404, { error: 'Tienda no encontrada.' });
    const key = req.headers['x-store-api-key'] || new URL(req.url, 'http://localhost').searchParams.get('key');
    const requestHost = String(req.headers.host || '').split(':')[0];
    const storeHost = new URL(store.origin).host;
    if (!safeEqual(key, store.apiKey) && origin !== store.origin && requestHost !== storeHost) return send(res, 401, { error: 'Clave API inválida.' });
    return send(res, 200, publicCatalog(store), 'application/json; charset=utf-8', { 'access-control-allow-origin': store.origin, 'access-control-allow-credentials': 'true', 'cache-control': 'no-store' });
  }
  const user = userFor(req); if (!user) return send(res, 401, { error: 'Autenticación requerida.' });
  const requestedStore = new URL(req.url, 'http://localhost').searchParams.get('storeId') || parts[3];
  const storeId = findStore(requestedStore)?.id || requestedStore;
  if (storeId && !canAccess(user, storeId)) return send(res, 403, { error: 'No tienes permiso para esta tienda.' });
  try {
    if (req.method === 'GET' && parts[2] === 'stores') return send(res, 200, { stores: db.data.stores.filter(s => user.role === 'master' || user.storeIds.includes(s.id)).map(s => ({ ...s, apiKey: user.role === 'master' ? s.apiKey : undefined })) });
    if (req.method === 'GET' && ['categories','products','settings'].includes(parts[2])) {
      const collection = parts[2] === 'settings' ? db.data.settings : db.data[parts[2]];
      return send(res, 200, parts[2] === 'settings' ? [settingsWithDefaults(findStore(storeId), collection.find(item => item.storeId === storeId))] : parts[2] === 'products' ? collection.filter(item => item.storeId === storeId).map(item => detailsForProduct(item, db.data.categories)) : collection.filter(item => item.storeId === storeId));
    }
    const collectionName = parts[2]; const collection = collectionName === 'settings' ? db.data.settings : db.data[collectionName];
    if (!collection || (collectionName !== 'stores' && !['categories','products','settings'].includes(collectionName))) return send(res, 404, { error: 'Recurso no encontrado.' });
    if (req.method === 'POST') {
      if (collectionName === 'stores' && user.role !== 'master') return send(res, 403, { error: 'Solo el usuario master puede crear tiendas.' });
      const input = await body(req); validateRecord(collectionName, input); if (collectionName === 'settings' && user.role !== 'master') { const current = collection.find(item => item.storeId === storeId) || {}; if (('logoUrl' in input && input.logoUrl !== current.logoUrl) || ('heroImageUrl' in input && input.heroImageUrl !== current.heroImageUrl)) return send(res, 403, { error: 'Solo el usuario master puede cambiar el logo y la imagen principal.' }); } const created = collectionName === 'stores' ? { ...input, id: id(), slug: cleanText(input.slug || input.name, 80).toLowerCase().replace(/[^a-z0-9]+/g, '-'), apiKey: crypto.randomBytes(32).toString('hex'), active: true, createdAt: now(), updatedAt: now() } : { ...input, id: id(), storeId, createdAt: now(), updatedAt: now() }; if (collectionName === 'settings') { const existing = collection.findIndex(x => x.storeId === storeId); if (existing >= 0) collection[existing] = { ...collection[existing], ...input, updatedAt: now() }; else collection.push(created); }
      else collection.push(created); await db.save(); return send(res, 201, collectionName === 'settings' ? settingsWithDefaults(findStore(storeId), collection.find(x => x.storeId === storeId)) : collectionName === 'products' ? detailsForProduct(created, db.data.categories) : created);
    }
    const itemId = parts[3]; const index = collection.findIndex(item => item.id === itemId && item.storeId === storeId); if (index < 0) return send(res, 404, { error: 'Registro no encontrado.' });
    if (req.method === 'PATCH') { const input = await body(req); validateRecord(collectionName, { ...collection[index], ...input }); collection[index] = { ...collection[index], ...input, id: itemId, storeId, updatedAt: now() }; await db.save(); return send(res, 200, collectionName === 'products' ? detailsForProduct(collection[index], db.data.categories) : collection[index]); }
    if (req.method === 'DELETE') { collection[index] = { ...collection[index], active: false, updatedAt: now() }; await db.save(); return send(res, 200, collection[index]); }
  } catch (error) { return send(res, 400, { error: error.message }); }
}

async function handleAdmin(req, res, pathname) {
  const query = new URL(req.url, 'http://localhost');
  if (pathname === '/storeadmin/login' && req.method === 'POST') { const input = await formBody(req); const user = db.data.users.find(u => u.email === String(input.email || '').toLowerCase()); if (!user || !verifyPassword(input.password || '', user.passwordHash)) return send(res, 401, loginPage('Correo o contraseña incorrectos.'), 'text/html; charset=utf-8'); const token = crypto.randomBytes(32).toString('hex'); sessions.set(token, user); return send(res, 302, '', 'text/plain', { location: '/storeadmin/', 'set-cookie': sessionCookie(token) }); }
  if (pathname === '/storeadmin/logout') { const token = cookie(req, 'stores_session'); sessions.delete(token); return send(res, 302, '', 'text/plain', { location: '/storeadmin/login', 'set-cookie': 'stores_session=; Max-Age=0; Path=/' }); }
  const user = userFor(req); if (!user) return pathname === '/storeadmin/login' ? send(res, 200, loginPage(), 'text/html; charset=utf-8') : redirect(res, '/storeadmin/login');
  if (pathname === '/storeadmin/' || pathname === '/storeadmin') { const accessible = db.data.stores.filter(s => canAccess(user, s.id)); return send(res, 200, shell(user, 'dashboard', 'Resumen', `<div class="grid"><div class="card"><h3>Tiendas</h3><div class="stat">${accessible.length}</div></div><div class="card"><h3>Productos activos</h3><div class="stat">${db.data.products.filter(p => accessible.some(s=>s.id===p.storeId) && p.active).length}</div></div><div class="card"><h3>Categorías activas</h3><div class="stat">${db.data.categories.filter(c => accessible.some(s=>s.id===c.storeId) && c.active).length}</div></div></div><br><div class="card"><h2>Acceso seguro</h2><p class="muted">La API verifica la sesión, el alcance de la tienda y el origen autorizado. Las claves no se exponen a usuarios de otras tiendas.</p></div>`), 'text/html; charset=utf-8'); }
  if (pathname === '/storeadmin/stores/new') { if (user.role !== 'master') return send(res, 403, 'Solo el usuario master puede crear tiendas.', 'text/plain; charset=utf-8'); return send(res, 200, shell(user, 'stores', 'Nueva tienda', storeAdminForm()), 'text/html; charset=utf-8'); }
  if (pathname === '/storeadmin/stores' && req.method === 'POST') {
    if (user.role !== 'master') return send(res, 403, 'Solo el usuario master puede crear tiendas.', 'text/plain; charset=utf-8');
    const input = await formBody(req); const name = cleanText(input.name, 160); const origin = cleanUrl(input.origin); const storeSlug = makeSlug(input.slug || name);
    const email = cleanText(input.adminEmail, 200).toLowerCase(); const password = String(input.adminPassword || '');
    if (!name || !origin || !storeSlug || !email || password.length < 8) return send(res, 400, shell(user, 'stores', 'Nueva tienda', storeAdminForm(input, 'Completa nombre, slug, origen, correo y una contraseña de mínimo 8 caracteres.')), 'text/html; charset=utf-8');
    if (db.data.stores.some(store => store.slug === storeSlug || store.origin === origin)) return send(res, 409, shell(user, 'stores', 'Nueva tienda', storeAdminForm(input, 'El slug o el origen ya están registrados.')), 'text/html; charset=utf-8');
    let admin = db.data.users.find(candidate => candidate.email === email);
    if (admin && admin.role === 'master') return send(res, 409, shell(user, 'stores', 'Nueva tienda', storeAdminForm(input, 'Ese correo pertenece al usuario master. Usa otro correo para el administrador de tienda.')), 'text/html; charset=utf-8');
    const createdAt = now(); const storeId = id(); const store = { id: storeId, name, slug: storeSlug, origin, apiKey: crypto.randomBytes(32).toString('hex'), active: true, createdAt, updatedAt: createdAt };
    if (!admin) { admin = { id: id(), email, passwordHash: hashPassword(password), role: 'store_admin', storeIds: [], createdAt }; db.data.users.push(admin); }
    admin.storeIds = [...new Set([...(admin.storeIds || []), storeId])]; db.data.stores.push(store); db.data.settings.push({ storeId, storeName: name, logoUrl: '', heroImageUrl: '', topbarText: '', whatsappNumber: '', whatsappMessage: '', whatsappGreeting: '', shippingNotice: '', purchaseInstructions: '', currency: 'COP', fractionDigits: 0, featuredTitle: 'Productos destacados', updatedAt: createdAt }); await db.save(); return redirect(res, '/storeadmin/stores');
  }
  const editMatch = pathname.match(/^\/storeadmin\/stores\/([^/]+)(?:\/edit)?$/);
  if (editMatch && pathname.endsWith('/edit')) { const store = db.data.stores.find(candidate => candidate.id === editMatch[1]); if (!store || !canAccess(user, store.id)) return send(res, 404, 'Tienda no encontrada.', 'text/plain; charset=utf-8'); return send(res, 200, shell(user, 'stores', `Editar ${text(store.name)}`, storeAdminForm(store)), 'text/html; charset=utf-8'); }
  if (editMatch && req.method === 'POST') {
    if (user.role !== 'master') return send(res, 403, 'Solo el usuario master puede editar tiendas.', 'text/plain; charset=utf-8');
    const store = db.data.stores.find(candidate => candidate.id === editMatch[1]); if (!store) return send(res, 404, 'Tienda no encontrada.', 'text/plain; charset=utf-8'); const input = await formBody(req); const name = cleanText(input.name, 160); const origin = cleanUrl(input.origin); const storeSlug = makeSlug(input.slug || name);
    if (!name || !origin || !storeSlug) return send(res, 400, shell(user, 'stores', 'Editar tienda', storeAdminForm({ ...store, ...input }, 'Completa nombre, slug y origen.')), 'text/html; charset=utf-8');
    if (db.data.stores.some(candidate => candidate.id !== store.id && (candidate.slug === storeSlug || candidate.origin === origin))) return send(res, 409, shell(user, 'stores', 'Editar tienda', storeAdminForm({ ...store, ...input }, 'El slug o el origen ya están registrados.')), 'text/html; charset=utf-8');
    Object.assign(store, { name, slug: storeSlug, origin, active: input.active === 'on', updatedAt: now() }); if (input.rotateApiKey === 'on') store.apiKey = crypto.randomBytes(32).toString('hex'); await db.save(); return redirect(res, '/storeadmin/stores');
  }
  if (pathname === '/storeadmin/stores') { const stores = db.data.stores.filter(s => canAccess(user,s.id)); return send(res, 200, shell(user,'stores','Tiendas',`${user.role === 'master' ? '<p class="muted">Crea tiendas nuevas, asigna administradores, actualiza el dominio y abre el panel específico de cada una.</p>' : ''}${storeList(user, stores)}`),'text/html; charset=utf-8'); }
  if (pathname === '/storeadmin/catalog/category' && req.method === 'POST') {
    const input = await formBody(req); const storeId = findStore(input.storeId)?.id; if (!storeId || !canAccess(user, storeId)) return send(res, 403, 'No tienes permiso para esta tienda.', 'text/plain; charset=utf-8');
    const category = input.id ? db.data.categories.find(item => item.id === input.id && item.storeId === storeId) : null; const name = cleanText(input.name, 120); if (!name) return send(res, 400, 'El nombre de la categoría es obligatorio.', 'text/plain; charset=utf-8');
    if (category) Object.assign(category, { name, description: cleanText(input.description, 240), imageUrl: cleanUrl(input.imageUrl), active: input.active === 'on', updatedAt: now() }); else db.data.categories.push({ id: id(), storeId, name, description: cleanText(input.description, 240), imageUrl: cleanUrl(input.imageUrl), active: true, sortOrder: Number(input.sortOrder || 0), createdAt: now(), updatedAt: now() });
    await db.save(); return redirect(res, `/storeadmin/catalog?storeId=${encodeURIComponent(storeId)}`);
  }
  if (pathname === '/storeadmin/catalog/product' && req.method === 'POST') {
    const input = await formBody(req); const storeId = findStore(input.storeId)?.id; if (!storeId || !canAccess(user, storeId)) return send(res, 403, 'No tienes permiso para esta tienda.', 'text/plain; charset=utf-8');
    const category = db.data.categories.find(item => item.id === input.categoryId && item.storeId === storeId); if (!category) return send(res, 400, 'La categoría no pertenece a la tienda seleccionada.', 'text/plain; charset=utf-8');
    const product = input.id ? db.data.products.find(item => item.id === input.id && item.storeId === storeId) : null; const name = cleanText(input.name, 160); const price = Number(input.price); if (!name || !Number.isFinite(price) || price < 0) return send(res, 400, 'Producto inválido.', 'text/plain; charset=utf-8');
    const values = { name, categoryId: category.id, price, imageUrl: cleanUrl(input.imageUrl), fallback: cleanText(input.fallback || '🛍️', 20), active: input.active === 'on', available: product ? product.available : true, featured: input.featured === 'on', updatedAt: now() };
    if (product) Object.assign(product, values); else db.data.products.push({ id: id(), storeId, description: '', previousPrice: null, gallery: [], badge: 'PRUEBA', sku: '', stock: null, sortOrder: Number(input.sortOrder || 0), createdAt: now(), ...values });
    await db.save(); return redirect(res, `/storeadmin/catalog?storeId=${encodeURIComponent(storeId)}`);
  }
  if (pathname === '/storeadmin/categories' || pathname === '/storeadmin/products') { const section = pathname.endsWith('/categories') ? 'categories' : 'products'; const stores = db.data.stores.filter(s => canAccess(user,s.id)); const selectedId = query.searchParams.get('storeId'); const title = section === 'categories' ? 'Categorías' : 'Productos'; return send(res,200,shell(user,section,title,centralCatalogPage(user, stores, selectedId, '', section, query.searchParams.get('categoryId')),catalogSidebar(stores, selectedId, section)),'text/html; charset=utf-8'); }
  if (pathname === '/storeadmin/catalog') { return redirect(res, '/storeadmin/categories'); }
  return send(res, 404, 'No encontrado', 'text/plain; charset=utf-8');
}

const server = http.createServer(async (req, res) => {
  try { const pathname = new URL(req.url, `http://${req.headers.host || 'localhost'}`).pathname; if (pathname.startsWith('/storeadmin/uploads/')) { const filename = path.basename(pathname); try { const file = await fs.readFile(path.join(uploadDir, filename)); return send(res, 200, file, 'image/webp; charset=binary', { 'cache-control': 'public, max-age=31536000, immutable' }); } catch { return send(res, 404, 'No encontrado', 'text/plain; charset=utf-8'); } } if (pathname.startsWith('/storeadmin/api/')) return await handleApi(req,res,pathname); if (pathname.startsWith('/storeadmin')) return await handleAdmin(req,res,pathname); return send(res, 404, 'No encontrado', 'text/plain; charset=utf-8'); }
  catch (error) { send(res, 500, { error: 'Error interno del servidor.' }); console.error(error); }
});

await fs.mkdir(uploadDir, { recursive: true });
await db.init(seed);
server.listen(port, () => console.log(`Stores Admin escuchando en http://localhost:${port}/storeadmin/`));
